/**
 * Render resume_tech.md / resume_finance.md. Pure, no dependency.
 *
 * WHY NOT A MARKDOWN LIBRARY. CLAUDE.md says ask before adding a dependency,
 * and this would be a parser, its transitive tree and its sanitiser surface for
 * six constructs. These files are not arbitrary markdown — they are GENERATED by
 * resume_from_pdf.py, from a grammar that file defines and test_resume_parity.py
 * pins. Everything that can appear here appears below.
 *
 * It renders exactly that grammar and nothing else:
 *
 *   # Name                     the H1
 *   Los Angeles, CA · …        the contact line, plain
 *   ---                        a rule between sections
 *   ## SECTION                 a section heading
 *   **Company** — Founder · … an entry line, bold lead
 *   B.S. Business Admin · …    an entry's second line (EDUCATION only)
 *   - bullet                   a bullet
 *   **Engineering:** Python…   a skills line
 *
 * Anything it does not recognise is rendered as a paragraph of PLAIN TEXT. It
 * never interprets HTML and never dangerouslySetInnerHTML — the input is a file
 * on disk today, but a renderer that would execute markup is a renderer that
 * becomes a hole the moment the input changes.
 */

/** Split `**bold** rest` into React children. The only inline construct used. */
export function inline(text) {
  const parts = String(text).split(/(\*\*[^*]+\*\*)/g).filter((s) => s !== "");
  return parts.map((p, i) =>
    p.startsWith("**") && p.endsWith("**")
      ? { bold: true, text: p.slice(2, -2), key: i }
      : { bold: false, text: p, key: i });
}

/**
 * The document as a flat list of blocks: {type, text} or {type:"ul", items:[]}.
 *
 * A list rather than nested structure because that is all the page needs, and
 * because a flat list is trivial to assert over — the test can say "the tech
 * document has 4 headings and 14 bullets" without walking a tree.
 */
export function blocks(md) {
  const out = [];
  const lines = String(md || "").split(/\r?\n/);   // \r?\n, always: see CLAUDE.md
  let list = null;

  const closeList = () => {
    if (list) { out.push({ type: "ul", items: list }); list = null; }
  };

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { closeList(); continue; }

    if (line.startsWith("- ")) {
      (list = list || []).push(line.slice(2));
      continue;
    }
    closeList();

    if (line === "---") out.push({ type: "hr" });
    else if (line.startsWith("## ")) out.push({ type: "h2", text: line.slice(3) });
    else if (line.startsWith("# ")) out.push({ type: "h1", text: line.slice(2) });
    else out.push({ type: "p", text: line });
  }
  closeList();
  return out;
}
